#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <algorithm>

class Solution {
public:
    int maxStudentsOnBench(std::vector<std::vector<int>>& students) {
        std::unordered_map<int, std::unordered_set<int>> bench_map;
        for (const auto& item : students) {
            bench_map[item[1]].insert(item[0]);
        }

        int max_students = 0;
        for (const auto& pair : bench_map) {
            max_students = std::max(max_students, (int)pair.second.size());
        }
        return max_students;
    }
};

import java.util.*;

class Solution {
    public int maxStudentsOnBench(int[][] students) {
        Map<Integer, Set<Integer>> benchMap = new HashMap<>();
        for (int[] item : students) {
            benchMap.computeIfAbsent(item[1], k -> new HashSet<>()).add(item[0]);
        }

        int maxStudents = 0;
        for (Set<Integer> set : benchMap.values()) {
            maxStudents = Math.max(maxStudents, set.size());
        }
        return maxStudents;
    }
}

var maxStudentsOnBench = function(students) {
    const benchMap = new Map();
    for (const [studentId, benchId] of students) {
        if (!benchMap.has(benchId)) benchMap.set(benchId, new Set());
        benchMap.get(benchId).add(studentId);
    }

    let maxStudents = 0;
    for (const set of benchMap.values()) {
        if (set.size > maxStudents) maxStudents = set.size;
    }
    return maxStudents;
};
